css:
.obj-group { margin-top: 26px; }
  .obj-group h3 { margin-bottom: 10px; }
  .obj { display: grid; grid-template-columns: 1fr 1.4fr; gap: 16px; padding: 16px 0; border-top: 1px solid var(--line); align-items: start; }
  .obj .q { font-family: var(--serif); font-size: 19px; line-height: 1.3; color: var(--ink); }
  .obj .q small { display: block; font-family: var(--sans); font-size: 11.5px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; margin-top: 6px; }
  .obj .q small.reflex { color: var(--ink-2); } .obj .q small.reason { color: var(--green); } .obj .q small.signal { color: #8a4a33; }
  .obj .a { font-size: 15.5px; color: var(--ink-2); margin: 0; }
  .obj .a b { color: var(--ink); font-weight: 600; }
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 16px; }
  .two-col > div { padding: 18px 20px; border-radius: 14px; background: #fff; border: 1px solid var(--line); }
  .two-col b { display: block; font-family: var(--serif); font-size: 20px; font-weight: 500; margin-bottom: 6px; }
  .two-col p { margin: 0; font-size: 15.5px; }
  @media (max-width: 820px) { .obj, .two-col { grid-template-columns: 1fr; } }
